// SDD §8 envelopes, measured on the reference environment (bench/config.json). Appends one JSON line per run to
// bench/results.jsonl, recording the machine actually observed (a hosted runner's hardware is not fixed).
//
//   node bench/run.mjs [--runs 5] [--no-append]
// E-S1: C-S1 → C-S4 on synthetic-it-assets.json ≤ 2 s wall-clock, CLI, cold (4 fresh node processes per run).
// E-S2: C-S4 on a 5,000-slot G1 schema's full proposal ≤ 5 s (generated by harness/props: G1 + correct proposal).
// E-S3: the default-budget prompt for synthetic-it-assets.json is one batch of ≤ 200,000 bytes.
// Each timed envelope is measured --runs times; the envelope binds the worst run.
import { spawnSync } from 'node:child_process';
import { mkdtempSync, readFileSync, readdirSync, writeFileSync, appendFileSync, rmSync, existsSync, statSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { tmpdir, cpus, totalmem, release, platform, arch } from 'node:os';
import { fileURLToPath, pathToFileURL } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const CLI = join(ROOT, 'src/cli/sdd.mjs');
const RUNS = Number(process.argv[process.argv.indexOf('--runs') + 1]) || 5;
const T = mkdtempSync(join(tmpdir(), 'sdd-bench-'));
const sdd = (...a) => { const r = spawnSync(process.execPath, [CLI, ...a], { cwd: ROOT, encoding: 'utf8', maxBuffer: 1 << 30 }); if (r.status > 1) throw new Error(`sdd ${a[0]}: exit ${r.status} ${r.stderr}`); return r; };
const ms = (f) => { const t = process.hrtime.bigint(); const v = f(); return [Number(process.hrtime.bigint() - t) / 1e6, v]; };
const out = { envelopes: {} };
let k = 0;

// E-S1
{
  const runs = [];
  for (let i = 0; i < RUNS; i++) {
    const d = join(T, `s1-${k++}`); const inv = join(T, `inv-${k}.jsonld`), sk = join(T, `sk-${k}.jsonld`);
    const [t, rep] = ms(() => {
      writeFileSync(inv, sdd('parse', join(ROOT, 'fixtures/jira-assets/synthetic-it-assets.json')).stdout);
      writeFileSync(sk, sdd('skeleton', inv).stdout);
      sdd('prompt', sk, inv, '--out-dir', d);
      return sdd('check', sk, join(d, 'prompt-1-of-1.txt'), join(ROOT, 'fixtures/witnesses/full/proposal-valid.txt'));
    });
    if (JSON.parse(rep.stdout).status !== 'validated') throw new Error('E-S1 chain did not validate');
    runs.push(Math.round(t));
  }
  out.envelopes['E-S1'] = { limitMs: 2000, runsMs: runs, worstMs: Math.max(...runs), pass: Math.max(...runs) <= 2000 };
}
// E-S3
{
  const d = join(T, 's3'); const inv = join(T, 's3-inv.jsonld'), sk = join(T, 's3-sk.jsonld');
  writeFileSync(inv, sdd('parse', join(ROOT, 'fixtures/jira-assets/synthetic-it-assets.json')).stdout);
  writeFileSync(sk, sdd('skeleton', inv).stdout); sdd('prompt', sk, inv, '--out-dir', d);
  const prompts = readdirSync(d).filter((f) => /^prompt-\d+-of-\d+\.txt$/.test(f));
  const bytes = prompts.map((f) => statSync(join(d, f)).size);
  out.envelopes['E-S3'] = { batches: prompts.length, bytes, pass: prompts.length === 1 && bytes[0] <= 200000 };
}
// E-S2
{
  const gen = join(ROOT, 'harness/props/bench-e-s2.mjs');
  if (!existsSync(gen)) out.envelopes['E-S2'] = { pass: null, note: 'not measured: harness/props/bench-e-s2.mjs (G1 5,000-slot schema + correct proposal) missing' };
  else {
    const { makeE_S2 } = await import(pathToFileURL(gen).href);
    const { schemaBytes, seed, slots } = await makeE_S2(5000);
    const sch = join(T, 's2.json'); writeFileSync(sch, schemaBytes);
    const inv = join(T, 's2-inv.jsonld'), sk = join(T, 's2-sk.jsonld'), d = join(T, 's2');
    writeFileSync(inv, sdd('parse', sch).stdout); writeFileSync(sk, sdd('skeleton', inv).stdout);
    sdd('prompt', sk, inv, '--budget', '100000000', '--out-dir', d);
    const prompt = join(d, 'prompt-1-of-1.txt');
    const { proposalFor } = await import(pathToFileURL(gen).href);
    const paste = join(T, 's2-paste.txt'); writeFileSync(paste, await proposalFor(readFileSync(prompt, 'utf8')));
    const runs = []; let status;
    for (let i = 0; i < RUNS; i++) { const [t, r] = ms(() => sdd('check', sk, prompt, paste)); status = JSON.parse(r.stdout).status; runs.push(Math.round(t)); }
    out.envelopes['E-S2'] = { seed, slots, status, limitMs: 5000, runsMs: runs, worstMs: Math.max(...runs), pass: status === 'validated' && Math.max(...runs) <= 5000 };
  }
}
rmSync(T, { recursive: true, force: true });
out.environment = { at: new Date().toISOString(), node: process.version, os: `${platform()} ${release()} ${arch()}`, cpu: cpus()[0]?.model, cpuCount: cpus().length, memoryBytes: totalmem(), runnerImage: process.env.ImageOS ? `${process.env.ImageOS} ${process.env.ImageVersion || ''}`.trim() : null, commit: process.env.GITHUB_SHA || null, conditions: `CLI, cold process per command, ${RUNS} runs, worst binds` };
if (!process.argv.includes('--no-append')) appendFileSync(join(ROOT, 'bench/results.jsonl'), JSON.stringify(out) + '\n');
console.log(JSON.stringify(out, null, 2));
const bad = Object.entries(out.envelopes).filter(([, v]) => v.pass === false);
process.exit(bad.length ? 1 : 0);
